// List of JS-callable commands. Keep in sync with `commands` module and
// with the permission manifests under `permissions/autogenerated/commands/`.
const COMMANDS: &[&str] = &["get_product", "purchase", "restore", "get_entitlement"];

// iOS only: StoreKit exists nowhere else. There is deliberately no
// Android path registered, so the Tauri CLI adds nothing to the Android Gradle
// build for this plugin and the Android app compiles exactly as before; the
// Rust side answers `supported: false` there.
fn main() {
    tauri_plugin::Builder::new(COMMANDS).ios_path("ios").build();
}
